head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setRowVisible]<br/>Body Row 의 인덱스를 사용하여 특정 Body Row 를 숨깁니다.",
    "validation" : [
        "rowIndex(필수) 파라미터는 Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨 (RowNum 표시).\n[MultiLine] 한 데이터 Row 의 두 줄은 같은 rowIndex (1줄 col1/col2, 2줄 col3/col4). 데이터 Row 0~2.\n[절차] rowIndex / visible 선택 -> setRowVisible 실행.\n[확인] setRowVisible(rowIndex, false) 실행 시 같은 rowIndex 의 두 줄(1줄+2줄)이 함께 숨겨지고, true 면 함께 표시됨 (getRowVisible 로 확인)."', '', 'label1');

    // dataList 생성 + 초기값 바인딩
    //  MultiLine 검증 : 한 데이터 Row 가 2줄에 걸쳐 표시되며 두 줄은 동일 rowIndex 를 가짐.
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "1250", "col3": "김영업", "col4": "010-1111-2222" },
        { "col1": "부산 해운대점", "col2": "980", "col3": "이판매", "col4": "010-3333-4444" },
        { "col1": "대구 수성점", "col2": "1430", "col3": "박상담", "col4": "010-5555-6666" }
    ]);

    // target 생성
    // ★ MultiLine : gBody 에 2개의 row 를 두어 한 데이터 Row 가 2줄에 걸쳐 표시되게 한다.
    //  - 1줄 : col1 / col2
    //  - 2줄 : col3 / col4
    //  - 두 줄은 동일 rowIndex (setRowVisible 은 한 데이터 Row(2줄)를 단일 rowIndex 로 함께 숨김/표시)
    //  rowNumVisible=true 로 RowNum 을 표시하여 숨김/표시 가시화.
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" rowNumVisible="true" dataList="data:dlt_bind" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="지점명"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="매출(만원)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="담당자"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="연락처"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="280" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 현재 표시중인 RowNum 순번 목록 수집 (재계산 없이 숨김 순번을 건너뛰는지 확인)
scwin.getDisplayedRowNums = function () {
    let arrNum = [];
    let tdList = document.querySelectorAll("td[id*='target1_headerRowNumber_bodyRow_']");
    for (var i = 0; i < tdList.length; i++) {
        if (tdList[i].offsetParent !== null) {
            let txt = tdList[i].textContent.trim();
            if (txt !== '') arrNum.push(txt);
        }
    }
    return arrNum;
}

// setRowVisible 실행 : 특정 데이터 Row 를 숨기거나 표시한다.
//  MultiLine : 같은 rowIndex 의 두 줄(1줄+2줄)이 함께 숨김/표시된다.
scwin.btn_setRowVisible_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let visibleStr = par_visible.getText();   // gdl_boolean 은 getValue 가 인덱스라 getText 로 'true'/'false' 판별

    let msg = '';
    if (visibleStr === '') {
        scwin.target1.setRowVisible(rowIndex);
        msg = "setRowVisible(" + rowIndex + ") [visible 생략] -> 데이터 Row " + rowIndex + " 의 2줄이 함께 숨김";
    } else {
        let visBool = (visibleStr === 'true');
        scwin.target1.setRowVisible(rowIndex, visBool);
        msg = "setRowVisible(" + rowIndex + ", " + visBool + ") -> 데이터 Row " + rowIndex + " 의 2줄이 함께 " + (visBool ? "표시" : "숨김");
    }

    // setRowVisible 후 그리드 재렌더가 비동기이므로 RowNum 은 setTimeout 으로 재렌더 후 읽음
    let isVisible = scwin.target1.getRowVisible(rowIndex);
    setTimeout(function () {
        let arrNum = scwin.getDisplayedRowNums();
        wf_body_bottom.getObj("scwin").setReturnValue(
            msg + "\n[getRowVisible(" + rowIndex + ")] " + isVisible
            + "\n[표시중 RowNum 순번] " + arrNum.join(', '));
    }, 300);
}
